   452	export function createManagedReviewEvidenceBinding(args: {
   453	  root: string;
   454	  storyId: string;
   455	  providerAgent: string;
   456	  lane: string;
   457	  reviewRunId: string;
   458	  runId: string;
   459	  receiptId: string;
   460	  expected: ManagedReviewExpectedBinding;
   461	  importedAt?: string;
   462	}): { binding: ManagedReviewEvidenceBinding; verification: ManagedReviewEvidenceVerification } {
   463	  let receipt: ManagedHostRunReceipt | null = null;
   464	  try {
   465	    receipt = managedHostRunReceipt(args.root, args.runId);
   466	  } catch {
   467	    // The shared evaluator below classifies missing/non-terminal receipt input;
   468	    // the importer does not maintain a parallel allow/deny vocabulary.
   469	  }
   470	  const binding: ManagedReviewEvidenceBinding = {
   471	    schemaVersion: 'lattice.managed_review_evidence_binding.v1',
   472	    runId: args.runId,
   473	    receiptId: args.receiptId,
   474	    proposalDigest: receipt?.evidenceProposalDigest ?? '',
   475	    terminalDigest: receipt?.terminalDigest ?? '',
   476	    importedAt: args.importedAt ?? new Date().toISOString(),
   477	    providerAgent: args.providerAgent,
   478	    providerHost: args.expected.providerHost,
   479	    lane: args.lane,
   480	    reviewRunId: args.reviewRunId,
   481	    headHash: args.expected.headHash,
   482	    materialHash: args.expected.materialHash,
   483	    storyFilesHash: args.expected.storyFilesHash,
   484	    promptHash: args.expected.promptHash,
   485	    envelopeId: args.expected.envelopeId,
   486	    managedPromptDigest: args.expected.managedPromptDigest,
   487	  };
   488	  const verification = verifyManagedReviewEvidence({
   489	    root: args.root,
   490	    storyId: args.storyId,
   491	    agent: args.providerAgent,
   492	    lane: args.lane,
   493	    reviewRunId: args.reviewRunId,
   494	    binding,
   495	    expected: args.expected,
