   226	export const defaultCodexReviewRunner: CodexReviewRunner = (opts): Promise<CodexReviewRunnerResult> => {
   227	  return new Promise<CodexReviewRunnerResult>((resolvePromise) => {
   228	    const child = spawn(
   229	      'codex',
   230	      ['exec', '-s', 'read-only', '-C', opts.storyWorktree],
   231	      {
   232	        cwd: opts.storyWorktree,
   233	        env: opts.env ?? process.env,
